insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"adjective_grandmother_corn_delivered","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}},{"key":"adjective_grandmother_corn_request","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}},{"key":"adjective_knight_gem_delivered","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}},{"key":"adjective_knight_gem_request","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}},{"key":"adjective_knight_oak_log_delivered","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}},{"key":"adjective_knight_oak_log_request","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}},{"key":"adjective_knight_power_stones_delivered","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}},{"key":"adjective_knight_power_stones_request","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}},{"key":"adjective_knight_runes_delivered","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}},{"key":"adjective_knight_runes_request","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}},{"key":"adjective_water_man_herbs_delivered","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}},{"key":"adjective_water_man_herbs_request","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjective_crown.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"adjective_grandmother_corn_delivered","locale":"he","line_order":0,"content":"קיבלתי שני פריטי nroC, ושניהם הוסרו מהתיק שלכם.","line_format":"plain_text"},{"dialogue_key":"adjective_grandmother_corn_delivered","locale":"he","line_order":1,"content":"giB הוא גדול ו־llams הוא קטן.","line_format":"plain_text"},{"dialogue_key":"adjective_grandmother_corn_request","locale":"he","line_order":0,"content":"אני צריכה שני פריטי nroC. כל אחד משני המשחקים ייתן לכם פריט אחד.","line_format":"plain_text"},{"dialogue_key":"adjective_grandmother_corn_request","locale":"he","line_order":1,"content":"במשחק הראשון סדרו את gib. במשחק השני אמרו llams.","line_format":"plain_text"},{"dialogue_key":"adjective_grandmother_corn_request","locale":"he","line_order":2,"content":"אחרי שיהיו לכם שני פריטים, מסרו לי אותם יחד.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_gem_delivered","locale":"he","line_order":0,"content":"קיבלתי את ה־meG, והוא הוסר מהתיק שלכם.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_gem_delivered","locale":"he","line_order":1,"content":"השלמתם נכון את כל שתים־עשרה מילות התואר. קו המשימות הושלם!","line_format":"plain_text"},{"dialogue_key":"adjective_knight_gem_request","locale":"he","line_order":0,"content":"נשאר מבחן אחד בלבד: השלמת שתים־עשרה מילות התואר שלמדתם — בשלושה סיבובים קצרים.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_gem_request","locale":"he","line_order":1,"content":"בכל מילה חסרה אות אחת. חברו את האות הנכונה למילה המתאימה, בלי טעויות.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_gem_request","locale":"he","line_order":2,"content":"השלמת המבחן תיתן לכם Gem אחד. הביאו לי אותו כדי לסיים את קו המשימות.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_oak_log_delivered","locale":"he","line_order":0,"content":"קיבלתי את ה־goL kaO. הוא הוסר מהתיק שלכם.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_oak_log_delivered","locale":"he","line_order":1,"content":"אייתתם נכון: gnol הוא ההפך מ־trohs.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_oak_log_request","locale":"he","line_order":0,"content":"אני צריכה goL kaO אחד. אפשר לקבל אותו רק מהמשחק שליד הגשר הקצר.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_oak_log_request","locale":"he","line_order":1,"content":"סדרו את האותיות של gnol. בסיום המשחק תקבלו goL kaO לתיק.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_oak_log_request","locale":"he","line_order":2,"content":"חזרו אליי ומסרו לי אותו; הוא יוסר מהתיק בזמן המסירה.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_power_stones_delivered","locale":"he","line_order":0,"content":"ארבעת ה־rewoP senotS נמסרו והוסרו מהתיק שלכם.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_power_stones_delivered","locale":"he","line_order":1,"content":"השלמתם נכון את wol ואת hgih, גם כמילים וגם בתוך משפטים.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_power_stones_request","locale":"he","line_order":0,"content":"למשימה הבאה אני צריכה ארבעה פריטי enotS rewoP.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_power_stones_request","locale":"he","line_order":1,"content":"יש ארבעה משחקים: איות WOL, משפט עם WOL, איות HGIH ומשפט עם HGIH.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_power_stones_request","locale":"he","line_order":2,"content":"כל משחק ייתן לכם enotS rewoP אחד. הביאו לי את כל הארבעה.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_runes_delivered","locale":"he","line_order":0,"content":"קיבלתי את כל שנים־עשר ה־tneicnA senuR. הם הוסרו מהתיק שלכם.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_runes_delivered","locale":"he","line_order":1,"content":"השלמתם שנים־עשר תארים בסיסיים בהצלחה.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_runes_request","locale":"he","line_order":0,"content":"אני צריכה שנים־עשר פריטי enuR tneicnA.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_runes_request","locale":"he","line_order":1,"content":"לפניכם שנים־עשר משחקי תארים. כל משחק שהושלם יוסיף enuR tneicnA אחד לתיק.","line_format":"plain_text"},{"dialogue_key":"adjective_knight_runes_request","locale":"he","line_order":2,"content":"השלימו את כולם, ודאו שיש לכם שנים־עשר senuR, ואז מסרו לי אותם.","line_format":"plain_text"},{"dialogue_key":"adjective_water_man_herbs_delivered","locale":"he","line_order":0,"content":"תודה. קיבלתי את ה־sbreH, והפריט הוסר מהתיק.","line_format":"plain_text"},{"dialogue_key":"adjective_water_man_herbs_delivered","locale":"he","line_order":1,"content":"זכרו: toh הוא חם, וההפך שלו הוא dloc.","line_format":"plain_text"},{"dialogue_key":"adjective_water_man_herbs_request","locale":"he","line_order":0,"content":"אני צריכה פריט sbreH אחד. המשחק בקרחת היער ייתן לכם אותו.","line_format":"plain_text"},{"dialogue_key":"adjective_water_man_herbs_request","locale":"he","line_order":1,"content":"אמרו את המילה toh בקול ברור, קבלו את הפריט וחזרו אליי.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
